/**
 * Complete Algerian administrative divisions, bilingual Arabic + French.
 *
 * - 58 wilayas (codes 01-58) and 1,541 municipalities (communes) with
 *   official administrative codes. Data is factual reference data.
 *
 * Source: HassanMak29/dz-wilaya-api (github.com/HassanMak29/dz-wilaya-api),
 *   src/data/wilayas.json @ main. Compiled from public open administrative
 *   datasets: ihahachi/Algeria-Cities (commune names AR/FR, daira, commune
 *   codes, coordinates) and Kenandarabeh/algeria-wilayas-communes-2026
 *   (postal codes). Fetched 2026-09-21.
 * Division: official administrative division of 2021 (48 -> 58 wilayas,
 *   Loi 19-12). Municipality codes are the official 4-digit ONS codes,
 *   zero-padded (e.g. Adrar commune 101 -> 0101).
 */

export type LocationType = 'wilaya' | 'municipality';

export interface LocationSeed {
  code: string;
  type: LocationType;
  parentCode?: string;
  nameAr: string;
  nameFr: string;
}

